examples.template:
VStack(spacing: theme.spacing.space4) {
    MonarchInstallVerify(
        snippets: [
            MonarchInstallSnippet({{snippets.0.label}}, code: {{snippets.0.code}}, description: {{snippets.0.description}}, id: {{snippets.0.id}}),
            MonarchInstallSnippet({{snippets.1.label}}, code: {{snippets.1.code}}, description: {{snippets.1.description}}, id: {{snippets.1.id}}),
            MonarchInstallSnippet({{snippets.2.label}}, code: {{snippets.2.code}}, description: {{snippets.2.description}}, id: {{snippets.2.id}}),
        ],
        status: connected ? .connected : .waiting,
        targets: [MonarchInstallTarget({{target.label}}, lastSeen: connected ? {{target.lastSeenAt|date}} : nil)],
        developerInstructions: {{developerInstructions}},
        testURL: URL(string: {{testHref}}),
        testHint: {{testHint}},
        now: {{now|date}}
    ) {
        MonarchInlineNotice({{credential}}, tone: .success)
    }
    MonarchButton(connected ? {{reset}} : {{simulate}}, variant: .secondary, size: .sm) {
        connected.toggle()
    }
}

examples.code:
VStack(spacing: theme.spacing.space4) {
    MonarchInstallVerify(
        snippets: [
            MonarchInstallSnippet("HTML", code: "<script src=\"https://cdn.example.com/widget.js\" data-key=\"pk_test_4f1a9c\" async></script>", description: "Paste it before the closing </body> tag on every page.", id: "html"),
            MonarchInstallSnippet("React", code: "import { Widget } from 'example-widget';\n\nexport function App() {\n  return <Widget publishableKey=\"pk_test_4f1a9c\" />;\n}", description: "Render it once, near the root of your app.", id: "react"),
            MonarchInstallSnippet("npm", code: "npm install example-widget", description: "Install the package, then use the React snippet.", id: "npm"),
        ],
        status: connected ? .connected : .waiting,
        targets: [MonarchInstallTarget("www.example.com", lastSeen: connected ? Date(timeIntervalSince1970: 1_768_046_340) : nil)],
        developerInstructions: "Add this snippet to every page of www.example.com: <script src=…>",
        testURL: URL(string: "https://example.com/try"),
        testHint: "A page running the real widget, so you can try it yourself.",
        now: Date(timeIntervalSince1970: 1_768_046_400)
    ) {
        MonarchInlineNotice("Publishable key ready. It only works on your listed websites.", tone: .success)
    }
    MonarchButton(connected ? "Reset demo" : "Simulate the site reporting in", variant: .secondary, size: .sm) {
        connected.toggle()
    }
}

MonarchInstallVerify(
    snippets: [MonarchInstallSnippet("npm", code: "npm install @example/widget", language: "bash")],
    status: .waiting,
    part: .install
) {
    MonarchCopyField("Site key", value: "pk_live_51H8example")
}
